using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using System.Text.RegularExpressions;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Features.Storefront;

namespace WhatsBiz.Infrastructure.Storefront;

public sealed class StorefrontFeedbackService(IConfiguration configuration, IStorefrontCustomerService customers) : IStorefrontFeedbackService
{
    private string ConnectionString => configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Database connection unavailable.");
    public async Task<StorefrontFeedbackTicketDto> SubmitAsync(string storeKey, string? sessionToken, StorefrontFeedbackInput input, CancellationToken token)
    {
        var tenant = await TenantAsync(storeKey, token) ?? throw new EntityNotFoundException("Store was not found.");
        var customer = string.IsNullOrWhiteSpace(sessionToken) ? null : await customers.GetSessionAsync(storeKey, sessionToken, token);
        var type = Normalize(input.FeedbackType, "SUGGESTION", "COMPLAINT"); var category = Normalize(input.Category, "ORDER", "PRODUCT", "DELIVERY", "PAYMENT_REFUND", "CUSTOMER_SERVICE", "OTHER");
        var subject = Required(input.Subject, 200, "Enter a subject."); var description = Required(input.Description, 4000, "Enter a description.");
        var guestName = customer is null ? Required(input.GuestName, 250, "Enter your name.") : null;
        var guestMobile = customer is null ? NormalizePhone(input.GuestMobile) : null;
        if (customer is null && guestMobile is null) throw new BusinessRuleException("Enter a valid mobile number.");
        await using var connection = new SqlConnection(ConnectionString); await connection.OpenAsync(token);
        if (input.OrderId is Guid orderId)
        {
            await using var order = new SqlCommand("SELECT COUNT(1) FROM sales.SalesInvoices i JOIN integration.WhatsAppCommerceOrders w ON w.TenantId=i.TenantId AND w.InvoiceId=i.InvoiceId AND w.SourceChannel=N'STOREFRONT' WHERE i.TenantId=@tenant AND i.InvoiceId=@order AND (@customer IS NULL OR i.CustomerId=@customer);", connection);
            Add(order, "@tenant", tenant); Add(order, "@order", orderId); Add(order, "@customer", customer?.Id);
            if ((int)(await order.ExecuteScalarAsync(token) ?? 0) != 1) throw new BusinessRuleException("The selected order is not available for this account.");
        }
        var ticketId = Guid.NewGuid(); var reference = $"FB-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
        await using var command = new SqlCommand("INSERT commerce.StorefrontFeedbackTickets(TicketId,TenantId,TicketReference,CustomerId,GuestName,GuestMobile,FeedbackType,Category,Subject,Description,OrderId) VALUES(@id,@tenant,@reference,@customer,@name,@mobile,@type,@category,@subject,@description,@order);", connection);
        Add(command, "@id", ticketId); Add(command, "@tenant", tenant); Add(command, "@reference", reference); Add(command, "@customer", customer?.Id); Add(command, "@name", guestName); Add(command, "@mobile", guestMobile); Add(command, "@type", type); Add(command, "@category", category); Add(command, "@subject", subject); Add(command, "@description", description); Add(command, "@order", input.OrderId);
        try { await command.ExecuteNonQueryAsync(token); } catch (SqlException ex) when (ex.Number is 2601 or 2627) { throw new BusinessRuleException("Please submit again in a moment."); }
        return new(ticketId, reference, type, category, subject, description, input.OrderId, "MEDIUM", "OPEN", null, DateTimeOffset.UtcNow, DateTimeOffset.UtcNow, customer?.Name, customer?.Mobile ?? guestMobile);
    }
    public async Task<IReadOnlyCollection<StorefrontFeedbackTicketDto>?> CustomerTicketsAsync(string storeKey, string sessionToken, CancellationToken token)
    { var customer = await customers.GetSessionAsync(storeKey, sessionToken, token); if (customer is null) return null; var tenant = await TenantAsync(storeKey, token); return tenant is null ? null : await TicketsAsync(tenant.Value, customer.Id, token); }
    public async Task<StorefrontFeedbackTicketDetailDto?> CustomerTicketAsync(string storeKey, string sessionToken, Guid ticketId, CancellationToken token)
    { var customer = await customers.GetSessionAsync(storeKey, sessionToken, token); var tenant = await TenantAsync(storeKey, token); return customer is null || tenant is null ? null : await DetailAsync(tenant.Value, ticketId, customer.Id, false, token); }
    public async Task<StorefrontFeedbackPageDto> SearchAsync(Guid tenantId, string? search, string? status, string? priority, int pageNumber, int pageSize, CancellationToken token)
    {
        pageNumber=Math.Clamp(pageNumber,1,1_000_000); pageSize=Math.Clamp(pageSize,1,100); search=Limit(search,100); status=Limit(status,20); priority=Limit(priority,10);
        await using var c=new SqlConnection(ConnectionString); await c.OpenAsync(token);
        const string countSql="SELECT COUNT(1),SUM(CASE WHEN Status IN(N'OPEN',N'REOPENED') THEN 1 ELSE 0 END),SUM(CASE WHEN Status=N'IN_PROGRESS' THEN 1 ELSE 0 END) FROM commerce.StorefrontFeedbackTickets WHERE TenantId=@tenant AND (@search IS NULL OR TicketReference LIKE N'%'+@search+N'%' OR Subject LIKE N'%'+@search+N'%' OR GuestMobile LIKE N'%'+@search+N'%') AND (@status IS NULL OR Status=@status) AND (@priority IS NULL OR Priority=@priority);";
        await using var count=new SqlCommand(countSql,c); Add(count,"@tenant",tenantId); Add(count,"@search",search); Add(count,"@status",status); Add(count,"@priority",priority); await using var cr=await count.ExecuteReaderAsync(token); await cr.ReadAsync(token); var total=cr.GetInt32(0); var open=cr.IsDBNull(1)?0:cr.GetInt32(1); var pending=cr.IsDBNull(2)?0:cr.GetInt32(2); await cr.CloseAsync();
        const string sql="SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE t.TenantId=@tenant AND (@search IS NULL OR t.TicketReference LIKE N'%'+@search+N'%' OR t.Subject LIKE N'%'+@search+N'%' OR t.GuestMobile LIKE N'%'+@search+N'%') AND (@status IS NULL OR t.Status=@status) AND (@priority IS NULL OR t.Priority=@priority) ORDER BY t.UpdatedAtUtc DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY;";
        await using var q=new SqlCommand(sql,c); Add(q,"@tenant",tenantId); Add(q,"@search",search); Add(q,"@status",status); Add(q,"@priority",priority); Add(q,"@skip",(pageNumber-1)*pageSize); Add(q,"@take",pageSize); var rows=new List<StorefrontFeedbackTicketDto>(); await using var r=await q.ExecuteReaderAsync(token); while(await r.ReadAsync(token)) rows.Add(ReadTicket(r)); return new(rows,total,pageNumber,pageSize,open,pending);
    }
    public Task<StorefrontFeedbackTicketDetailDto?> GetAsync(Guid tenantId, Guid ticketId, bool includeInternal, CancellationToken token) => DetailAsync(tenantId,ticketId,null,includeInternal,token);
    public async Task<StorefrontFeedbackTicketDetailDto> UpdateAsync(Guid tenantId, Guid actorUserId, Guid ticketId, UpdateStorefrontFeedbackInput input, CancellationToken token)
    {
        var current=await GetAsync(tenantId,ticketId,true,token)??throw new EntityNotFoundException("Feedback ticket was not found."); var status=input.Status is null?current.Ticket.Status:Normalize(input.Status,"OPEN","IN_PROGRESS","RESOLVED","CLOSED","REOPENED"); var priority=input.Priority is null?current.Ticket.Priority:Normalize(input.Priority,"LOW","MEDIUM","HIGH","URGENT");
        if(input.CustomerReply is null&&input.InternalNote is null&&status==current.Ticket.Status&&priority==current.Ticket.Priority&&!input.AssignedTo.HasValue) return current;
        await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var tx=await c.BeginTransactionAsync(token);
        await using(var q=new SqlCommand("UPDATE commerce.StorefrontFeedbackTickets SET Status=@status,Priority=@priority,AssignedTo=COALESCE(@assigned,AssignedTo),CustomerVisibleReply=COALESCE(@reply,CustomerVisibleReply),UpdatedAtUtc=SYSUTCDATETIME(),ResolvedAtUtc=CASE WHEN @status IN(N'RESOLVED',N'CLOSED') THEN COALESCE(ResolvedAtUtc,SYSUTCDATETIME()) ELSE NULL END WHERE TenantId=@tenant AND TicketId=@id;",c,(SqlTransaction)tx)){Add(q,"@status",status);Add(q,"@priority",priority);Add(q,"@assigned",input.AssignedTo);Add(q,"@reply",string.IsNullOrWhiteSpace(input.CustomerReply)?null:Limit(input.CustomerReply,4000));Add(q,"@tenant",tenantId);Add(q,"@id",ticketId);await q.ExecuteNonQueryAsync(token);}
        await using(var a=new SqlCommand("INSERT commerce.StorefrontFeedbackTicketActivity(TenantId,TicketId,ActivityType,FromStatus,ToStatus,CustomerReply,InternalNote,ActorUserId) VALUES(@tenant,@id,N'UPDATE',@from,@to,@reply,@note,@actor);",c,(SqlTransaction)tx)){Add(a,"@tenant",tenantId);Add(a,"@id",ticketId);Add(a,"@from",current.Ticket.Status);Add(a,"@to",status);Add(a,"@reply",input.CustomerReply);Add(a,"@note",input.InternalNote);Add(a,"@actor",actorUserId);await a.ExecuteNonQueryAsync(token);} await tx.CommitAsync(token); return await GetAsync(tenantId,ticketId,true,token) ?? throw new EntityNotFoundException("Feedback ticket was not found.");
    }
    private async Task<IReadOnlyCollection<StorefrontFeedbackTicketDto>> TicketsAsync(Guid tenant,Guid customer,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=new SqlCommand("SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE t.TenantId=@tenant AND t.CustomerId=@customer ORDER BY t.UpdatedAtUtc DESC;",c);Add(q,"@tenant",tenant);Add(q,"@customer",customer);var rows=new List<StorefrontFeedbackTicketDto>();await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))rows.Add(ReadTicket(r));return rows;}
    private async Task<StorefrontFeedbackTicketDetailDto?> DetailAsync(Guid tenant,Guid id,Guid? customer,bool includeInternal,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);var sql="SELECT t.TicketId,t.TicketReference,t.FeedbackType,t.Category,t.Subject,t.Description,t.OrderId,t.Priority,t.Status,t.CustomerVisibleReply,t.CreatedAtUtc,t.UpdatedAtUtc,COALESCE(c.CustomerName,t.GuestName),COALESCE(c.Mobile,t.GuestMobile) FROM commerce.StorefrontFeedbackTickets t LEFT JOIN sales.Customers c ON c.TenantId=t.TenantId AND c.CustomerId=t.CustomerId WHERE t.TenantId=@tenant AND t.TicketId=@id"+(customer.HasValue?" AND t.CustomerId=@customer":"")+";";await using var q=new SqlCommand(sql,c);Add(q,"@tenant",tenant);Add(q,"@id",id);Add(q,"@customer",customer);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))return null;var ticket=ReadTicket(r);await r.CloseAsync();var activities=new List<StorefrontFeedbackActivityDto>();var activitySql="SELECT ActivityType,FromStatus,ToStatus,CustomerReply,CreatedAtUtc FROM commerce.StorefrontFeedbackTicketActivity WHERE TenantId=@tenant AND TicketId=@id ORDER BY CreatedAtUtc";await using var a=new SqlCommand(activitySql,c);Add(a,"@tenant",tenant);Add(a,"@id",id);await using var ar=await a.ExecuteReaderAsync(token);while(await ar.ReadAsync(token))activities.Add(new(ar.GetString(0),ar.IsDBNull(1)?null:ar.GetString(1),ar.IsDBNull(2)?null:ar.GetString(2),ar.IsDBNull(3)?null:ar.GetString(3),ar.GetDateTimeOffset(4)));return new(ticket,activities);}
    private static StorefrontFeedbackTicketDto ReadTicket(SqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.IsDBNull(6)?null:r.GetGuid(6),r.GetString(7),r.GetString(8),r.IsDBNull(9)?null:r.GetString(9),r.GetDateTimeOffset(10),r.GetDateTimeOffset(11),r.IsDBNull(12)?null:r.GetString(12),r.IsDBNull(13)?null:r.GetString(13));
    private async Task<Guid?> TenantAsync(string key,CancellationToken token){await using var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=new SqlCommand("SELECT TenantId FROM core.Tenants WHERE TenantKey=@key AND IsActive=1",c);Add(q,"@key",key.Trim().ToUpperInvariant());return await q.ExecuteScalarAsync(token) is Guid id?id:null;}
    private static string Required(string? value,int max,string message){var x=value?.Trim();if(string.IsNullOrWhiteSpace(x)||x.Length>max)throw new BusinessRuleException(message);return x;}
    private static string Normalize(string? value,params string[] allowed){var x=value?.Trim().ToUpperInvariant();if(x is null||!allowed.Contains(x))throw new BusinessRuleException("The selected feedback value is invalid.");return x;}
    private static string? Limit(string? value,int max)=>string.IsNullOrWhiteSpace(value)?null:value.Trim()[..Math.Min(value.Trim().Length,max)];
    private static string? NormalizePhone(string? value){var x=Regex.Replace(value??"", "[^0-9]", "");return x.Length is >=10 and <=15?x:null;}
    private static void Add(SqlCommand c,string n,object? v)=>c.Parameters.AddWithValue(n,v??DBNull.Value);
}
